function basename(pathText) {
  let lastSlash = -1;
  for (let index = 0; index < pathText.length; index += 1) {
    const char = pathText[index];
    if (char === '/' || char === '\\') {
      lastSlash = index;
    }
  }
  if (lastSlash === -1) {
    return pathText;
  }
  return pathText.slice(lastSlash + 1);
}

function usage(programName) {
  return `usage: ${programName} [-h] --a A`;
}

function help(programName) {
  return `${usage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;
}

function looksLikeNegativeNumber(token) {
  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  const first = token[1];
  return (first >= '0' && first <= '9') || first === '.';
}

export function parseCommandLine(argv, scriptPath = 'test16.mjs') {
  const programName = basename(scriptPath);
  let value;
