export function splitLines(source) {
  const lines = [];
  let start = 0;

  for (let index = 0; index < source.length; index += 1) {
    if (source[index] === '\n') {
      let text = source.slice(start, index);
      if (text.endsWith('\r')) {
        text = text.slice(0, text.length - 1);
      }
      lines.push({ text, hasBreak: true });
      start = index + 1;
    }
  }

  if (start < source.length) {
    let text = source.slice(start);
    if (text.endsWith('\r')) {
      text = text.slice(0, text.length - 1);
    }
    lines.push({ text, hasBreak: false });
